#!/usr/bin/env python3
import argparse, json, mimetypes, os, stat, sys, time
from pathlib import Path

def is_text_file(path, sample=1024):
    try:
        with open(path, 'rb') as f:
            chunk = f.read(sample)
        return b'\x00' not in chunk
    except:
        return False

def guess_language(path):
    ext = Path(path).suffix.lower()
    lang_map = {
        '.py': 'python', '.js': 'javascript', '.mjs': 'javascript',
        '.ts': 'typescript', '.html': 'html', '.css': 'css',
        '.json': 'json', '.yaml': 'yaml', '.yml': 'yaml',
        '.sh': 'bash', '.bash': 'bash', '.zsh': 'zsh',
        '.md': 'markdown', '.txt': 'text', '.log': 'log',
        '.xml': 'xml', '.sql': 'sql', '.conf': 'config',
        '.ini': 'ini', '.cfg': 'config',
    }
    if ext in lang_map:
        return lang_map[ext]
    if is_text_file(path):
        try:
            with open(path, 'r', errors='ignore') as f:
                first = f.readline().strip()
            if first.startswith('#!'):
                if 'python' in first: return 'python'
                if 'node' in first: return 'javascript'
                if 'bash' in first or 'sh' in first: return 'bash'
        except:
            pass
    mime, _ = mimetypes.guess_type(path)
    if mime:
        if 'text' in mime: return 'text'
        if 'javascript' in mime: return 'javascript'
        if 'json' in mime: return 'json'
    return 'unknown'

def file_preview(path, max_lines=5):
    if not is_text_file(path):
        return "[binary]"
    try:
        with open(path, 'r', errors='ignore') as f:
            lines = [f.readline() for _ in range(max_lines)]
        return ''.join(line.rstrip('\n') for line in lines if line)
    except Exception as e:
        return f"[error: {e}]"

def scan_directory(root_dir, max_depth=None, pattern=None, extensions=None, preview=0):
    results = []
    root = Path(root_dir).resolve()
    for dirpath, dirnames, filenames in os.walk(root):
        if max_depth is not None:
            rel_depth = len(Path(dirpath).relative_to(root).parts)
            if rel_depth >= max_depth:
                dirnames.clear()
        for fname in filenames:
            full = os.path.join(dirpath, fname)
            if pattern and not Path(fname).match(pattern):
                continue
            if extensions:
                ext = Path(fname).suffix.lower()
                if ext not in extensions:
                    continue
            try:
                st = os.stat(full)
            except OSError:
                continue
            entry = {
                'path': full,
                'size': st.st_size,
                'mtime': time.ctime(st.st_mtime),
                'is_symlink': stat.S_ISLNK(st.st_mode),
                'extension': Path(fname).suffix.lower() or '<none>',
                'language': guess_language(full),
                'type': 'text' if is_text_file(full) else 'binary',
            }
            if preview > 0 and entry['type'] == 'text':
                entry['preview'] = file_preview(full, preview)
            results.append(entry)
    return results

def output_table(data):
    if not data:
        print("No files found.")
        return
    headers = ['Path', 'Size', 'Modified', 'Type', 'Lang']
    col_widths = [50, 10, 26, 8, 12]
    header_line = '  '.join(h.ljust(w) for h, w in zip(headers, col_widths))
    print(header_line)
    print('-' * len(header_line))
    for e in data:
        row = [e['path'][-50:], str(e['size']), e['mtime'], e['type'], e['language']]
        print('  '.join(str(f).ljust(w) for f, w in zip(row, col_widths)))
        if 'preview' in e:
            print(f"    Preview: {e['preview'][:120]}...")
            print()

def main():
    parser = argparse.ArgumentParser(description='Investigate files - DeepSeek toolkit')
    parser.add_argument('directory', nargs='?', default='.', help='Directory to scan')
    parser.add_argument('--max-depth', type=int, default=None)
    parser.add_argument('--pattern', type=str, default=None)
    parser.add_argument('--extensions', type=str, default=None, help='Comma-separated exts (e.g. .py,.js)')
    parser.add_argument('--preview', type=int, default=0, help='Preview lines for text files')
    parser.add_argument('--output', choices=['json','table'], default='table')
    args = parser.parse_args()

    exts = None
    if args.extensions:
        exts = [e.strip().lower() if e.startswith('.') else f'.{e.strip().lower()}'
                for e in args.extensions.split(',')]

    data = scan_directory(
        args.directory,
        max_depth=args.max_depth,
        pattern=args.pattern,
        extensions=exts,
        preview=args.preview
    )

    if args.output == 'json':
        print(json.dumps(data, indent=2, ensure_ascii=False))
    else:
        output_table(data)

if __name__ == '__main__':
    main()
